custom_css:
@import url("https://cdn.jsdelivr.net/npm/lxgw-wenkai-screen-webfont@1.7.0/style.css");
@import url("https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600&family=Cormorant+Garamond:ital,wght@1,500&display=swap");

/* 十二时辰·辰·苏醒 ｜ theme by if love
   物件：晨前的蓝墙，每条消息是墙上推开的一扇窗 */

/* ========== 01 tokens ========== */
:root {
  --chen-wall: #21397F;
  --chen-wall-deep: #172B63;
  --chen-wall-soft: #2B4793;
  --chen-wall-hover: #3A5AA6;
  --chen-line: #4562AE;
  --chen-window: #CFE2F5;
  --chen-window-hi: #E3EEF9;
  --chen-window-lo: #A9C6E8;
  --chen-cloud: #F3F6FB;
  --chen-field: #E6EEF9;
  --chen-ink: #1A2F66;
  --chen-ink-deep: #0F2563;
  --chen-ink-soft: #4C66A6;
  --chen-placeholder: #5A70A8;
  --chen-text: #E9F0FA;
  --chen-mist: #A9BEE6;
  --chen-mist-dim: #7F9AD6;
  --chen-dawn: #F2C38E;
  --chen-dawn-deep: #D99A55;
  --chen-dawn-soft: #F6D9B4;
  --chen-danger: #E89AA6;

  --chen-font-body: "LXGW WenKai Screen", "Noto Serif SC", "Songti SC", "STSong", serif;
  --chen-font-title: "Noto Serif SC", "Songti SC", "STSong", serif;
  --chen-font-num: "Cormorant Garamond", "Times New Roman", serif;

  --mainFontFamily: var(--chen-font-body) !important;
  --shadowWidth: 0 !important;
  --SmartThemeShadowColor: transparent !important;
}

body {
  font-family: var(--chen-font-body);
  background-color: var(--chen-wall);
}

/* ========== 02 scrollbar（只藏外观，不动滚动） ========== */
::-webkit-scrollbar {
  display: none !important;
}

* {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

/* ========== 03 去发光 / 去投影 ========== */
:is(.fa-solid, .fa-regular, .fa-brands, .menu_button, .mes_button, .drawer-icon, .right_menu_button,
    .interactable, #send_but, #mes_stop, #options_button, #extensionsMenuButton,
    .welcomePanel .fa-solid, .popup-button-close, .inline-drawer-icon) {
  filter: none !important;
  text-shadow: none !important;
}

:is(.menu_button, .drawer-content, #top-bar, #send_form, .popup, .mes, .inline-drawer-header) {
  box-shadow: none !important;
}

/* ========== 04 背景墙 ========== */
#bg1 {
  background-color: var(--chen-wall) !important;
  background-image: url("data:image/webp;base64,") !important;
  background-size: cover !important;
  background-position: center !important;
}

/* ========== 05 顶栏 ========== */
#top-bar {
  background: var(--chen-wall-deep) !important;
  backdrop-filter: none !important;
  border: none !important;
}

#top-settings-holder {
  background: transparent !important;
}

#top-settings-holder .drawer-icon {
  color: var(--chen-mist) !important;
  opacity: 1 !important;
}

#top-settings-holder .drawer-icon.openIcon,
#top-settings-holder .drawer-toggle:hover .drawer-icon {
  color: var(--chen-dawn) !important;
}

#top-settings-holder .drawer-icon::before {
  content: "" !important;
  display: block;
  width: 24px;
  height: 24px;
  margin: auto;
  background-color: currentColor;
  -webkit-mask: var(--chen-icon) center / contain no-repeat;
  mask: var(--chen-icon) center / contain no-repeat;
}

#ai-config-button .drawer-icon { --chen-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23000%22%20stroke-width%3D%221.6%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M5%203v18M12%203v18M19%203v18%22%2F%3E%3Ccircle%20cx%3D%225%22%20cy%3D%229%22%20r%3D%222.2%22%20fill%3D%22%23000%22%2F%3E%3Ccircle%20cx%3D%2212%22%20cy%3D%2215%22%20r%3D%222.2%22%20fill%3D%22%23000%22%2F%3E%3Ccircle%20cx%3D%2219%22%20cy%3D%227%22%20r%3D%222.2%22%20fill%3D%22%23000%22%2F%3E%3C%2Fsvg%3E"); }
#sys-settings-button .drawer-icon { --chen-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23000%22%20stroke-width%3D%221.6%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M9%203v5M15%203v5M6%208h12v3a6%206%200%200%201-12%200zM12%2017v4%22%2F%3E%3C%2Fsvg%3E"); }
#advanced-formatting-button .drawer-icon { --chen-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23000%22%20stroke-width%3D%221.6%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M4%2020l4.5-1L19%208.5%2015.5%205%205%2015.5z%22%2F%3E%3Cpath%20d%3D%22M13.5%207l3.5%203.5%22%2F%3E%3C%2Fsvg%3E"); }
#WI-SP-button .drawer-icon { --chen-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23000%22%20stroke-width%3D%221.6%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M3%205.5c3-1.2%206-1%209%201%203-2%206-2.2%209-1v13c-3-1.2-6-1-9%201-3-2-6-2.2-9-1z%22%2F%3E%3Cpath%20d%3D%22M12%206.5v13%22%2F%3E%3C%2Fsvg%3E"); }
#user-settings-button .drawer-icon { --chen-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23000%22%20stroke-width%3D%221.6%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Ccircle%20cx%3D%2212%22%20cy%3D%2212%22%20r%3D%223.8%22%2F%3E%3Cpath%20d%3D%22M12%202.5v2.6M12%2018.9v2.6M2.5%2012h2.6M18.9%2012h2.6M5.3%205.3l1.8%201.8M16.9%2016.9l1.8%201.8M5.3%2018.7l1.8-1.8M16.9%207.1l1.8-1.8%22%2F%3E%3C%2Fsvg%3E"); }
#backgrounds-button .drawer-icon { --chen-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23000%22%20stroke-width%3D%221.6%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Crect%20x%3D%225.5%22%20y%3D%223%22%20width%3D%2213%22%20height%3D%2216%22%20rx%3D%220.5%22%2F%3E%3Cpath%20d%3D%22M12%203v16M5.5%2011h13M3%2021h18%22%2F%3E%3C%2Fsvg%3E"); }
#extensions-settings-button .drawer-icon { --chen-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23000%22%20stroke-width%3D%221.6%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Ccircle%20cx%3D%2212%22%20cy%3D%226.6%22%20r%3D%223%22%2F%3E%3Ccircle%20cx%3D%2217.1%22%20cy%3D%2210.4%22%20r%3D%223%22%2F%3E%3Ccircle%20cx%3D%2215.2%22%20cy%3D%2216.4%22%20r%3D%223%22%2F%3E%3Ccircle%20cx%3D%228.8%22%20cy%3D%2216.4%22%20r%3D%223%22%2F%3E%3Ccircle%20cx%3D%226.9%22%20cy%3D%2210.4%22%20r%3D%223%22%2F%3E%3Ccircle%20cx%3D%2212%22%20cy%3D%2212%22%20r%3D%221.3%22%20fill%3D%22%23000%22%2F%3E%3C%2Fsvg%3E"); }
#persona-management-button .drawer-icon { --chen-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23000%22%20stroke-width%3D%221.6%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Ccircle%20cx%3D%2211%22%20cy%3D%2212%22%20r%3D%227.5%22%2F%3E%3Cpath%20d%3D%22M7.5%2010.5l3-3M8%2014l5.5-5.5%22%2F%3E%3Cpath%20d%3D%22M19%202.5l.7%201.8%201.8.7-1.8.7-.7%201.8-.7-1.8-1.8-.7%201.8-.7z%22%20fill%3D%22%23000%22%20stroke%3D%22none%22%2F%3E%3C%2Fsvg%3E"); }
#rightNavHolder .drawer-icon { --chen-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23000%22%20stroke-width%3D%221.6%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M6%2021V10a6%206%200%200%201%2012%200v11z%22%2F%3E%3Cpath%20d%3D%22M6%2015h12M12%204v17%22%2F%3E%3C%2Fsvg%3E"); }

#top-settings-holder .redOverlayGlow,
#top-settings-holder .drawer-icon.redOverlayGlow {
  color: var(--chen-danger) !important;
}

/* ========== 06 抽屉面板 ========== */
#top-settings-holder .drawer-content,
#left-nav-panel,
#right-nav-panel,
#floatingPrompt,
#cfgConfig,
#logprobsViewer {
  background:
    linear-gradient(rgba(20, 36, 86, 0.86), rgba(20, 36, 86, 0.86)),
    url("data:image/webp;base64,") center / cover !important;
  background-color: var(--chen-wall-deep) !important;
  backdrop-filter: none !important;
  border: 1px solid rgba(169, 198, 232, 0.28) !important;
  border-radius: 6px !important;
  color: var(--chen-text);
}

:is(#top-settings-holder .drawer-content, #left-nav-panel, #right-nav-panel) h3,
:is(#top-settings-holder .drawer-content, #left-nav-panel, #right-nav-panel) h4 {
  font-family: var(--chen-font-title);
  letter-spacing: 0.15em;
  color: var(--chen-text);
}

/* 扩展面板折叠栏：换掉默认灰渐变，做成一扇窗 */
#extensions_settings .inline-drawer-header,
#extensions_settings2 .inline-drawer-header,
.drawer-content .inline-drawer-header {
  background: var(--chen-window) !important;
  background-image: none !important;
  color: var(--chen-ink) !important;
  border: 1px solid var(--chen-cloud) !important;
  border-radius: 3px !important;
  box-shadow: inset 0 0 0 3px #DCE9F7, inset 0 0 0 4px var(--chen-window-lo) !important;
  padding: 7px 12px !important;
  letter-spacing: 0.12em;
}

#extensions_settings .inline-drawer-header *,
#extensions_settings2 .inline-drawer-header *,
.drawer-content .inline-drawer-header * {
  color: var(--chen-ink) !important;
}

#extensions_settings .inline-drawer-content,
#extensions_settings2 .inline-drawer-content {
  background: rgba(23, 43, 99, 0.6);
  border: 1px solid rgba(169, 198, 232, 0.2);
  border-top: none;
  border-radius: 0 0 4px 4px;
  padding: 8px 10px;
}

/* ========== 07 聊天：每层一扇窗 ========== */
#chat {
  background: transparent !important;
  padding-top: 30px;
}

#chat .mes[is_system="false"] {
  --av: 104px;
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  padding: 18px 10px 34px !important;
  background: transparent !important;
  border: none !important;
}

#chat .mes[is_user="true"] {
  --av: 88px;
}

/* 头像：大圆镜 */
#chat .mes[is_system="false"] > .mesAvatarWrapper {
  display: flex;
  flex-direction: row-reverse;
  align-items: flex-end;
  align-self: flex-start;
  gap: 16px;
  position: relative !important;
  z-index: 5 !important;
  padding: 0 0 0 2px;
  margin: 0;
}

#chat .mes[is_user="true"] > .mesAvatarWrapper {
  flex-direction: row;
  align-self: flex-end;
  padding: 0 2px 0 0;
}

#chat .mes[is_system="false"] .avatar {
  position: relative !important;
  margin: 0 !important;
  padding: 0 !important;
  box-sizing: border-box;
  width: var(--av) !important;
  height: var(--av) !important;
  min-width: var(--av);
  flex: 0 0 var(--av);
  border-radius: 50% !important;
  overflow: visible !important;
  border: none !important;
  background: linear-gradient(160deg, #E3EEF9, #A9C6E8);
}

#chat .mes[is_system="false"] .avatar img {
  position: absolute !important;
  inset: 5% !important;
  width: 90% !important;
  height: 90% !important;
  max-width: none !important;
  margin: 0 !important;
  padding: 0 !important;
  transform: none !important;
  border-radius: 50% !important;
  object-fit: cover;
  border: none !important;
  box-shadow: none !important;
}

#chat .mes[is_system="false"] .avatar::after {
  content: "";
  position: absolute;
  inset: calc(var(--av) * -0.16);
