/* 楼层/耗时/token：竖排在镜子旁 */
#chat .mes[is_system="false"] .mesIDDisplay {
  font-size: 0 !important;
}

#chat .mes[is_system="false"] :is(.mes_timer, .tokenCounterDisplay) {
  writing-mode: vertical-rl;
  font-family: var(--chen-font-num);
  font-style: italic;
  font-size: 12px !important;
  letter-spacing: 0.1em;
  color: var(--chen-mist) !important;
  opacity: 1 !important;
  margin: 6px 0 0 !important;
  padding: 0 !important;
  align-self: flex-start;
}

#chat .mes[is_system="false"]::before {
  content: "第 " attr(mesid) " 扇窗";
  position: absolute;
  top: calc(18px + var(--av) * 0.48 - 22px);
  left: calc(var(--av) + 62px);
  font-family: var(--chen-font-title);
  font-size: 11px;
  letter-spacing: 0.3em;
  color: var(--chen-mist);
  pointer-events: none;
  z-index: 2;
}

#chat .mes[is_user="true"]::before {
  left: auto;
  right: calc(var(--av) + 62px);
}

/* 楼层分隔：一只小蝴蝶 */
#chat .mes[is_system="false"]::after {
  content: "";
  position: absolute;
  left: 15%;
  right: 15%;
  bottom: 6px;
  height: 18px;
  background:
    url("data:image/webp;base64,") center / 18px auto no-repeat,
    repeating-linear-gradient(90deg, #5571B8 0 2px, transparent 2px 7px) left center / 42% 1px no-repeat,
    repeating-linear-gradient(90deg, #5571B8 0 2px, transparent 2px 7px) right center / 42% 1px no-repeat;
  pointer-events: none;
}

#chat .mes.last_mes::after {
  content: none;
}

/* 消息块：名字在墙上，正文在窗里 */
#chat .mes[is_system="false"] > .mes_block {
  position: relative !important;
  z-index: 1 !important;
  isolation: isolate;
  margin-top: calc(var(--av) * -0.52) !important;
  padding: 0 !important;
  min-width: 0;
}

#chat .mes[is_system="false"] > .mes_block::before {
  content: "";
  position: absolute;
  inset: 34px 0 0 0;
  z-index: -1;
  border-style: solid;
  border-width: 22px 18px 9px 16px;
  border-color: #4A62A0 #2C4A9E #E2CBA0 #EBD6AE;
  border-image: url("data:image/webp;base64,") 56 50 23 44 stretch;
  background:
    url("data:image/webp;base64,") right 112px top 44px / 24px auto no-repeat,
    url("data:image/webp;base64,") right -2px top 6px / 104px auto no-repeat,
    linear-gradient(180deg, #4A9BE2 0, #8DC2EF 70px, #D3E6F8 150px, #EAF2FB 230px, #EEF4FB 100%);
  background-color: #8EC0EE;
  pointer-events: none;
}

/* 用户：纯白卡片 */
#chat .mes[is_user="true"] > .mes_block::before {
  inset: 34px 0 0 0;
  border: 1px solid #FFFFFF;
  border-image: none;
  border-radius: 18px 6px 18px 18px;
  background: #FFFFFF;
}

/* 名字行 */
#chat .mes[is_system="false"] .ch_name {
  position: relative !important;
  display: flex !important;
  height: 34px !important;
  min-height: 34px !important;
  flex-shrink: 0;
  margin: 0 !important;
  align-items: flex-start;
  padding-left: calc(var(--av) + 62px);
  padding-right: 0;
}

#chat .mes[is_user="true"] .ch_name {
  flex-direction: row-reverse;
  padding-left: 0;
  padding-right: calc(var(--av) + 62px);
}

#chat .mes[is_user="true"] .ch_name > .flex-container.flex1 {
  flex-direction: row-reverse;
}

#chat .mes .name_text {
  font-family: var(--chen-font-title) !important;
  font-size: 17px !important;
  font-weight: 400;
  letter-spacing: 0.25em;
  color: var(--chen-text) !important;
}

#chat .mes .ch_name > .flex-container.flex1 {
  flex-wrap: nowrap !important;
  min-width: 0;
  overflow: hidden;
}

#chat .mes .timestamp {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
  font-family: var(--chen-font-num);
  font-style: italic;
  font-size: 12px !important;
  color: var(--chen-dawn) !important;
  opacity: 1 !important;
}

#chat .mes .mes_buttons,
#chat .mes .mes_edit_buttons {
  color: var(--chen-mist);
}

#chat .mes :is(.mes_button, .extraMesButtonsHint, .mes_edit_buttons .menu_button) {
  color: var(--chen-mist) !important;
  opacity: 1 !important;
  background: transparent !important;
  border: none !important;
}

#chat .mes :is(.mes_button, .extraMesButtonsHint):hover {
  color: var(--chen-dawn) !important;
}

/* 正文 */
#chat .mes[is_system="false"] .mes_text {
  position: relative;
  color: var(--chen-ink) !important;
  font-family: var(--chen-font-body) !important;
  font-size: 15px;
  line-height: 1.95;
  letter-spacing: 0.06em;
  padding: 0 22px 22px 26px !important;
}

#chat .mes[is_system="false"] .mes_text::before {
  content: "";
  display: block;
  height: calc(var(--av) * 0.52 - 6px);
}

#chat .mes[is_user="true"][is_system="false"] .mes_text {
  padding-bottom: 8px !important;
}

#chat .mes[is_user="true"][is_system="false"] .mes_text::before {
  height: calc(var(--av) * 0.52 - 4px);
}

#chat .mes .mes_reasoning_details + .mes_text::before {
  height: 4px;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text {
  padding-right: 30px !important;
}

#chat .mes .mes_text p {
  margin: 0 0 0.6em;
}

#chat .mes[is_system="false"] .mes_text q {
  color: var(--chen-ink-deep) !important;
  text-decoration: underline dotted var(--chen-dawn-deep);
  text-decoration-thickness: 2px;
  text-underline-offset: 5px;
}

#chat .mes[is_system="false"] .mes_text em,
#chat .mes[is_system="false"] .mes_text i {
  font-style: normal !important;
  color: #3D5A9E !important;
  -webkit-text-emphasis: dot #8FAEDC;
  text-emphasis: dot #8FAEDC;
  -webkit-text-emphasis-position: under;
  text-emphasis-position: under right;
}

#chat .mes[is_system="false"] .mes_text strong,
#chat .mes[is_system="false"] .mes_text b {
  color: var(--chen-ink-deep) !important;
  font-weight: 600;
  background: var(--chen-dawn-soft);
  padding: 0 3px;
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
}

#chat .mes[is_system="false"] .mes_text u {
  text-decoration: underline wavy var(--chen-ink-soft);
  text-underline-offset: 4px;
}

#chat .mes[is_system="false"] .mes_text blockquote {
  margin: 0.6em 0;
  padding: 0.5em 0.9em;
  border: 1px dashed #8FAEDC;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.4);
  color: var(--chen-ink-soft);
}

#chat .mes[is_system="false"] .mes_text a {
  color: var(--chen-ink-deep) !important;
  text-decoration: underline dotted;
}

#chat .mes[is_system="false"] .mes_text hr {
  border: none;
  height: 1px;
  background: repeating-linear-gradient(90deg, #8FAEDC 0 2px, transparent 2px 7px);
  margin: 1em 0;
}

#chat .mes .mes_text code {
  background: var(--chen-window-hi) !important;
  color: var(--chen-ink-deep) !important;
  border: 1px solid var(--chen-window-lo);
  border-radius: 3px;
  padding: 0 4px;
}

#chat .mes .mes_text pre {
  background: #EEF4FB !important;
  border: 1px solid var(--chen-window-lo) !important;
  border-radius: 4px;
  padding: 10px 12px !important;
  overflow-x: auto;
}

#chat .mes .mes_text pre code,
#chat .mes .mes_text pre code.hljs {
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  color: var(--chen-ink) !important;
  font-family: var(--chen-font-body) !important;
  font-size: 13.5px !important;
  line-height: 1.75 !important;
  letter-spacing: 0.04em;
}

#chat .mes .mes_text pre code * {
  color: inherit !important;
  background: transparent !important;
}

#chat .mes .mes_text pre code :is(.hljs-tag, .hljs-name, .hljs-keyword, .hljs-attr, .hljs-title, .hljs-section) {
  color: var(--chen-ink-soft) !important;
}

#chat .mes .mes_text pre code :is(.hljs-string, .hljs-number, .hljs-literal) {
  color: #8A5A22 !important;
}

#chat .mes .mes_text pre code .hljs-comment {
  color: var(--chen-placeholder) !important;
  font-style: italic;
}

#chat .mes .mes_text ::selection {
  background: var(--chen-dawn-soft);
  color: var(--chen-ink-deep);
}

/* 思考块 */
#chat .mes .mes_reasoning_details {
  margin: 40px 18px 0 !important;
  padding: 6px 10px;
  background: rgba(255, 255, 255, 0.45) !important;
  border: 1px dashed #8FAEDC !important;
  border-radius: 3px;
  color: var(--chen-ink-soft) !important;
  position: relative;
}

#chat .mes .mes_reasoning_details * {
  color: var(--chen-ink-soft) !important;
  opacity: 1 !important;
}



/* 编辑态 */
#chat .mes .edit_textarea,
#chat .mes .reasoning_edit_textarea {
  background: var(--chen-cloud) !important;
  color: var(--chen-ink) !important;
  border: 1px solid var(--chen-window-lo) !important;
  border-radius: 3px;
  font-family: var(--chen-font-body);
  margin: 40px 10px 10px;
  width: calc(100% - 20px);
}

/* 翻页 */
#chat .mes :is(.swipe_left, .swipe_right) {
  color: var(--chen-ink) !important;
  background: rgba(243, 246, 251, 0.92);
  border-radius: 50%;
  opacity: 1 !important;
  width: 26px;
  height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
}

#chat .mes .swipes-counter {
  color: var(--chen-mist) !important;
  font-family: var(--chen-font-num);
  font-style: italic;
  opacity: 1 !important;
}

/* 系统消息 */
#chat .mes[is_system="true"] .mes_text,
#chat .mes[is_system="true"] .name_text {
  color: var(--chen-mist) !important;
}

/* ========== 08 输入栏 ========== */
#send_form {
  position: relative;
  background: var(--chen-wall-deep) !important;
  border: 1px solid var(--chen-line) !important;
  border-radius: 8px !important;
  backdrop-filter: none !important;
}

#send_textarea {
  background: var(--chen-field) !important;
  color: var(--chen-ink) !important;
  font-family: var(--chen-font-body) !important;
  letter-spacing: 0.06em;
  border: none !important;
  border-radius: 3px !important;
  box-shadow: inset 0 0 0 1px var(--chen-window-lo) !important;
  padding: 8px 10px !important;
}

#send_textarea::placeholder {
  color: var(--chen-placeholder) !important;
  opacity: 1;
}

:is(#options_button, #extensionsMenuButton, #mes_continue, #mes_impersonate) {
  color: var(--chen-mist) !important;
  opacity: 1 !important;
}

:is(#options_button, #extensionsMenuButton, #mes_continue, #mes_impersonate):hover {
  color: var(--chen-dawn) !important;
}

#options_button::before,
#extensionsMenuButton::before,
#send_but::before,
#mes_stop .fa-solid::before {
  content: "" !important;
  display: block;
  width: 22px;
  height: 22px;
  margin: auto;
  background-color: currentColor;
  -webkit-mask: var(--chen-icon) center / contain no-repeat;
  mask: var(--chen-icon) center / contain no-repeat;
}

#options_button { --chen-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23000%22%20stroke-width%3D%221.6%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M4%205h16M4%2010h16M4%2015h16M12%2015v4%22%2F%3E%3Ccircle%20cx%3D%2212%22%20cy%3D%2220.2%22%20r%3D%221.2%22%20fill%3D%22%23000%22%2F%3E%3C%2Fsvg%3E"); }
#extensionsMenuButton { --chen-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23000%22%20stroke-width%3D%221.6%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M10%203l1.6%204.9L16.5%209.5l-4.9%201.6L10%2016l-1.6-4.9L3.5%209.5l4.9-1.6z%22%2F%3E%3Cpath%20d%3D%22M18%2014l.8%202.2%202.2.8-2.2.8-.8%202.2-.8-2.2-2.2-.8%202.2-.8z%22%2F%3E%3C%2Fsvg%3E"); }
#send_but { --chen-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23000%22%20stroke-width%3D%221.6%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M3%2019h18M7%2019a5%205%200%200%201%2010%200%22%2F%3E%3Cpath%20d%3D%22M12%203v9M8.5%206.5L12%203l3.5%203.5%22%2F%3E%3C%2Fsvg%3E"); }
#mes_stop .fa-solid { --chen-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23000%22%20stroke-width%3D%221.6%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Ccircle%20cx%3D%2212%22%20cy%3D%2212%22%20r%3D%229%22%2F%3E%3Crect%20x%3D%228.5%22%20y%3D%228.5%22%20width%3D%227%22%20height%3D%227%22%20rx%3D%221%22%20fill%3D%22%23000%22%2F%3E%3C%2Fsvg%3E"); }

#send_but {
  width: 36px !important;
  height: 36px !important;
  border-radius: 50%;
  background: var(--chen-dawn) !important;
  color: var(--chen-ink) !important;
  opacity: 1 !important;
  align-items: center;
  justify-content: center;
}

#send_but:hover {
  background: var(--chen-dawn-soft) !important;
}

#mes_stop {
  color: var(--chen-dawn) !important;
  opacity: 1 !important;
}

/* 输入栏弹出菜单 */
#options .options-content,
#extensionsMenu,
.list-group {
  background: var(--chen-wall-deep) !important;
  border: 1px solid var(--chen-line) !important;
  border-radius: 6px !important;
  backdrop-filter: none !important;
  color: var(--chen-text) !important;
}

#options .options-content a,
#extensionsMenu .list-group-item,
.list-group .list-group-item {
  color: var(--chen-text) !important;
  opacity: 1 !important;
}

#options .options-content a:hover,
#extensionsMenu .list-group-item:hover,
.list-group .list-group-item:hover {
  background: var(--chen-wall-soft) !important;
  color: var(--chen-dawn) !important;
}

/* ========== 09 通用控件 ========== */
:is(#top-settings-holder .drawer-content, #left-nav-panel, #right-nav-panel, #floatingPrompt, #cfgConfig, #character_popup, #form_create)
  :is(input[type="text"], input[type="number"], input[type="search"], input[type="password"], input[type="url"], input[type="email"], select, textarea),
.text_pole {
  background: var(--chen-field) !important;
  color: var(--chen-ink) !important;
  border: 1px solid var(--chen-window-lo) !important;
  border-radius: 3px !important;
  box-shadow: none !important;
}

:is(#top-settings-holder .drawer-content, #left-nav-panel, #right-nav-panel, #floatingPrompt, #cfgConfig, #character_popup, #form_create, .popup)
  :is(input, textarea)::placeholder,
.text_pole::placeholder {
  color: var(--chen-placeholder) !important;
  opacity: 1 !important;
}

select option {
  background: var(--chen-field);
  color: var(--chen-ink);
}

.menu_button {
  background: var(--chen-wall-soft) !important;
  color: var(--chen-text) !important;
  border: 1px solid var(--chen-line) !important;
  border-radius: 3px !important;
  opacity: 1 !important;
}

.menu_button:hover {
  background: var(--chen-wall-hover) !important;
  color: var(--chen-dawn) !important;
}

.menu_button:is(.active, .toggleEnabled, .selected) {
  background: var(--chen-dawn) !important;
  color: var(--chen-ink) !important;
  border-color: var(--chen-dawn-deep) !important;
}

.menu_button:is(.disabled, [disabled]) {
  background: #24407F !important;
  color: var(--chen-mist-dim) !important;
}

:focus-visible {
  outline: 2px solid var(--chen-dawn) !important;
  outline-offset: 2px;
}

input[type="checkbox"] {
  background-color: var(--chen-field) !important;
  border: 1px solid var(--chen-window-lo) !important;
  opacity: 1 !important;
}

input[type="checkbox"]:checked::before {
  box-shadow: inset 1em 1em var(--chen-ink) !important;
}

input[type="radio"] {
  accent-color: var(--chen-dawn);
}

input[type="range"] {
  accent-color: var(--chen-dawn);
}

input[type="range"]::-webkit-slider-thumb {
  background: var(--chen-dawn) !important;
  border: 1px solid var(--chen-dawn-deep) !important;
  box-shadow: none !important;
}

input[type="range"]::-moz-range-thumb {
  background: var(--chen-dawn) !important;
  border: 1px solid var(--chen-dawn-deep) !important;
  box-shadow: none !important;
}

/* 角色标签 */
.tags .tag {
  background: var(--chen-wall-soft) !important;
  color: var(--chen-text) !important;
  border: 1px solid var(--chen-line) !important;
  opacity: 1 !important;
  filter: none !important;
}

.tags .tag.selected {
  background: var(--chen-dawn) !important;
  color: var(--chen-ink) !important;
}

.tags .tag.excluded {
  background: #5B2E54 !important;
  color: #F6D9E2 !important;
}

/* Select2 */
.select2-container .select2-selection,
.select2-dropdown {
  background: var(--chen-field) !important;
  color: var(--chen-ink) !important;
  border: 1px solid var(--chen-window-lo) !important;
}

.select2-container .select2-selection__choice {
  background: var(--chen-window) !important;
  color: var(--chen-ink) !important;
  border: 1px solid var(--chen-window-lo) !important;
}

.select2-results__option,
.select2-selection__rendered,
.select2-search__field {
  color: var(--chen-ink) !important;
}

.select2-results__option--highlighted {
  background: var(--chen-dawn-soft) !important;
}

/* 预设条目管理 */
#completion_prompt_manager_list,
#completion_prompt_manager .text_pole {
  background: transparent !important;
  border: none !important;
  color: var(--chen-text) !important;
}

#completion_prompt_manager .completion_prompt_manager_prompt,
#completion_prompt_manager .completion_prompt_manager_list_head {
  background: var(--chen-wall-soft) !important;
  border: 1px solid var(--chen-line) !important;
  border-radius: 3px;
  margin-bottom: 4px;
  opacity: 1 !important;
  filter: none !important;
}

#completion_prompt_manager .completion_prompt_manager_prompt * {
  color: var(--chen-text);
  opacity: 1 !important;
  filter: none !important;
}

#completion_prompt_manager .completion_prompt_manager_prompt :is(.fa-solid, .fa-regular, .drag-handle, .prompt_manager_prompt_tokens, span.fa-fw) {
  color: var(--chen-mist) !important;
}

#completion_prompt_manager .completion_prompt_manager_prompt .fa-trash-can,
#completion_prompt_manager .completion_prompt_manager_prompt .prompt-manager-detach-action {
  color: var(--chen-danger) !important;
}

#completion_prompt_manager .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
  background: #22397A !important;
  border-style: dashed !important;
}

#completion_prompt_manager .completion_prompt_manager_prompt_disabled :is(*, .fa-solid, .fa-regular) {
  color: var(--chen-mist-dim) !important;
}

#completion_prompt_manager .completion_prompt_manager_prompt_disabled :is(.prompt-manager-toggle-action, .prompt-manager-edit-action) {
  color: var(--chen-mist) !important;
}

/* 面板里的代码 */
:is(.drawer-content, .popup) pre,
:is(.drawer-content, .popup) code {
  background: #EAF2FB !important;
  color: var(--chen-ink) !important;
}

/* ========== 10 弹窗（含历史聊天）：浅色窗，深字 ========== */
.popup,
#dialogue_popup,
#character_popup,
.shadow_popup .dialogue_popup {
  --SmartThemeBodyColor: #1A2F66;
  --SmartThemeEmColor: #4C66A6;
  --SmartThemeQuoteColor: #0F2563;
  --SmartThemeUnderlineColor: #1A2F66;
  background: #EAF2FB !important;
  color: var(--chen-ink) !important;
  border: 1px solid var(--chen-window-lo) !important;
  border-radius: 6px !important;
  backdrop-filter: none !important;
}

.popup :is(h1, h2, h3, h4, label, small, span, div),
#dialogue_popup :is(h1, h2, h3, h4, label, small, span) {
  color: inherit;
}

.popup :is(input[type="text"], input[type="search"], input[type="number"], select, textarea) {
  background: #FFFFFF !important;
  color: var(--chen-ink) !important;
  border: 1px solid var(--chen-window-lo) !important;
}

.popup .menu_button {
  background: var(--chen-wall-soft) !important;
  color: var(--chen-text) !important;
}

.popup .menu_button:hover {
  background: var(--chen-wall-hover) !important;
}

.select_chat_block {
  background: #FFFFFF !important;
  border: 1px solid var(--chen-window-lo) !important;
  border-radius: 4px !important;
  color: var(--chen-ink) !important;
  opacity: 1 !important;
}

.select_chat_block * {
  color: var(--chen-ink) !important;
  opacity: 1 !important;
}

.select_chat_block[highlight="true"],
.select_chat_block:hover {
  background: var(--chen-dawn-soft) !important;
}

/* 通知 */
#toast-container > div {
  background-color: #EAF2FB !important;
  color: var(--chen-ink) !important;
  border: 1px solid var(--chen-window-lo) !important;
  opacity: 1 !important;
  box-shadow: none !important;
}

#toast-container > .toast-error {
  background-color: #F8E3E7 !important;
  color: #6A2234 !important;
}

#toast-container > .toast-warning {
  background-color: var(--chen-dawn-soft) !important;
  color: #5A3510 !important;
}

/* 欢迎页 */
.welcomePanel {
  background: rgba(23, 43, 99, 0.85) !important;
  border: 1px solid rgba(169, 198, 232, 0.25) !important;
  border-radius: 6px;
}

.welcomePanel :is(.fa-solid, .fa-regular, .menu_button) {
  color: var(--chen-mist) !important;
}

/* ========== 11 手机 ========== */
@media (max-width: 700px) {
  #chat .mes[is_system="false"] {
    --av: 92px;
    padding: 16px 6px 34px !important;
  }

  #chat .mes[is_user="true"] {
    --av: 76px;
  }

  #chat .mes[is_system="false"] .mes_text {
    font-size: 15px;
    line-height: 1.9;
    padding-left: 24px !important;
    padding-right: 22px !important;
  }

  #chat .mes[is_user="false"][is_system="false"] .mes_text {
    padding-right: 26px !important;
  }

}
